#ifndef ZOVUTILS_DU_BACKEND_H
#define ZOVUTILS_DU_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
typedef struct{int all,apparent,human,one,follow,maxdepth,depth_set;long maxdepth_val;int status;}zov_duopt;
static inline unsigned long long zov_du_size(const struct stat*s,zov_duopt*o){if(o->apparent)return (unsigned long long)s->st_size;if(s->st_blocks>0)return ((unsigned long long)s->st_blocks+1)/2;return ((unsigned long long)s->st_size+1023)/1024;}
static inline void zov_du_print(unsigned long long n,const char*path,zov_duopt*o){if(o->human){double v=(double)n;const char*u="K";if(v>=1024){v/=1024;u="M";}if(v>=1024){v/=1024;u="G";}if(v>=1024){v/=1024;u="T";}if(v<10)printf("%.1f%s\t%s\n",v,u,path);else printf("%.0f%s\t%s\n",v,u,path);}else printf("%llu\t%s\n",n,path);}
static inline unsigned long long zov_du_walk(const char*path,zov_duopt*o,int depth){struct stat st;int rc=o->follow?stat(path,&st):lstat(path,&st);if(rc<0){fprintf(stderr,"du: cannot access '%s': %s\n",path,strerror(errno));o->status=1;return 0;}unsigned long long total=S_ISDIR(st.st_mode)?0:zov_du_size(&st,o);if(S_ISDIR(st.st_mode)&&depth<1024){DIR*d=opendir(path);if(!d){fprintf(stderr,"du: cannot read directory '%s': %s\n",path,strerror(errno));o->status=1;}else{struct dirent*de;while((de=readdir(d))){if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;size_t a=strlen(path),b=strlen(de->d_name);char*p=(char*)malloc(a+b+2);if(!p){o->status=1;continue;}memcpy(p,path,a);size_t n=a;if(n&&p[n-1]!='/')p[n++]='/';memcpy(p+n,de->d_name,b+1);unsigned long long sub=zov_du_walk(p,o,depth+1);total+=sub;free(p);}closedir(d);}if((o->one&&depth==0)||(!o->one&&(!o->depth_set||depth<=o->maxdepth_val)))zov_du_print(total,path,o);}else if((o->all||depth==0)&&(!o->depth_set||depth<=o->maxdepth_val))zov_du_print(total,path,o);return total;}
static inline int zov_du_run(int argc,char**argv){zov_duopt o={0,0,0,0,0,0,0,0,0};const char**paths=(const char**)malloc((size_t)(argc+1)*sizeof(char*));if(!paths)return 1;int nf=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: du [OPTION]... [FILE]...\nSummarize disk usage of the set of FILEs, recursively for directories.\n  -a, --all             write counts for all files, not just directories\n  -b, --bytes           equivalent to --apparent-size --block-size=1\n  -h, --human-readable  print sizes in human readable format\n  -L, --dereference     follow all symbolic links\n  -s, --summarize       display only a total for each argument\n  -d, --max-depth=N     print totals for directories at most N levels deep\n      --help            display this help and exit\n      --version         output version information and exit");free(paths);return 0;}if(!strcmp(a,"--version")){puts("du (zovutils) 0.10.1");free(paths);return 0;}if(!strcmp(a,"-a")||!strcmp(a,"--all")){o.all=1;continue;}if(!strcmp(a,"-s")||!strcmp(a,"--summarize")){o.one=1;continue;}if(!strcmp(a,"-h")||!strcmp(a,"--human-readable")){o.human=1;continue;}if(!strcmp(a,"-b")||!strcmp(a,"--bytes")){o.apparent=1;continue;}if(!strcmp(a,"-L")||!strcmp(a,"--dereference")){o.follow=1;continue;}if(!strcmp(a,"-d")||!strcmp(a,"--max-depth")){if(i+1>=argc){free(paths);return 1;}o.maxdepth_val=strtol(argv[++i],NULL,10);o.depth_set=1;continue;}if(!strncmp(a,"--max-depth=",12)){o.maxdepth_val=strtol(a+12,NULL,10);o.depth_set=1;continue;}if(a[0]=='-'&&a[1]&&a[1]!='-'){for(size_t j=1;a[j];j++){if(a[j]=='a')o.all=1;else if(a[j]=='s')o.one=1;else if(a[j]=='h')o.human=1;else if(a[j]=='b')o.apparent=1;else if(a[j]=='L')o.follow=1;else{fprintf(stderr,"du: invalid option -- '%c'\nTry 'du --help' for more information.\n",a[j]);free(paths);return 1;}}continue;}if(a[0]=='-'&&a[1]=='-'){fprintf(stderr,"du: unrecognized option '%s'\nTry 'du --help' for more information.\n",a);free(paths);return 1;}paths[nf++]=a;}if(!nf)paths[nf++]=".";for(int i=0;i<nf;i++)zov_du_walk(paths[i],&o,0);free(paths);return o.status;}
#endif
